:root {
  --bg: #1a1c2c;
  --card: #2d2f45;
  --primary: #ff6b6b;
  --accent: #4ecdc4;
  --text: #f7f7f7;
  --shadow: #0d0e15;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  padding: 1rem;
  color: var(--text);
}

.pomodoro-card {
  background: var(--card);
  border-radius: 12px;
  padding: 2rem 1.5rem;
  width: 100%;
  max-width: 400px;
  text-align: center;
  box-shadow: 0 8px 0 var(--shadow);
  border: 2px solid var(--shadow);
}

.title {
  font-size: 1.25rem;
  letter-spacing: 2px;
  margin-bottom: 1.5rem;
  color: var(--primary);
  font-weight: 700;
}

.mode-indicator {
  font-size: 1rem;
  letter-spacing: 3px;
  margin-bottom: 0.5rem;
  color: var(--accent);
  font-weight: 600;
}

.countdown {
  font-size: 4.5rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  line-height: 1.2;
  margin-bottom: 1.5rem;
  color: var(--text);
}

.controls {
  display: flex;
  gap: 0.75rem;
  justify-content: center;
  margin-bottom: 1.5rem;
}

.btn {
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 600;
  padding: 0.75rem 1.5rem;
  border: 2px solid var(--shadow);
  border-radius: 8px;
  background: var(--primary);
  color: var(--bg);
  cursor: pointer;
  box-shadow: 0 4px 0 var(--shadow);
  transition: transform 0.05s, box-shadow 0.05s;
  min-width: 100px;
}

.btn:hover {
  filter: brightness(1.1);
}

.btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.btn:active {
  transform: translateY(3px);
  box-shadow: 0 1px 0 var(--shadow);
}

.mode-switch {
  display: flex;
  gap: 0.75rem;
  justify-content: center;
}

.mode-btn {
  font-family: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  padding: 0.5rem 1rem;
  border: 2px solid var(--shadow);
  border-radius: 8px;
  background: var(--bg);
  color: var(--text);
  cursor: pointer;
  box-shadow: 0 3px 0 var(--shadow);
  transition: transform 0.05s, box-shadow 0.05s;
}

.mode-btn:hover {
  background: #2a2d3e;
}

.mode-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.mode-btn:active {
  transform: translateY(2px);
  box-shadow: 0 1px 0 var(--shadow);
}

.mode-btn.active {
  background: var(--accent);
  color: var(--bg);
}

@media (max-width: 400px) {
  .pomodoro-card {
    padding: 1.5rem 1rem;
  }
  .countdown {
    font-size: 3.5rem;
  }
  .btn {
    font-size: 1rem;
    padding: 0.6rem 1rem;
    min-width: 80px;
  }
  .mode-btn {
    font-size: 0.85rem;
    padding: 0.4rem 0.75rem;
  }
}

const WORK_TIME = 25 * 60;
const BREAK_TIME = 5 * 60;

let mode = 'work';
let timeLeft = WORK_TIME;
let timerId = null;
let endTime = null;
let isRunning = false;

const timerEl = document.getElementById('timer');
const modeEl = document.getElementById('mode');
const startPauseBtn = document.getElementById('startPause');
const resetBtn = document.getElementById('reset');
const workBtn = document.getElementById('workBtn');
const breakBtn = document.getElementById('breakBtn');

function formatTime(seconds) {
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

function updateDisplay() {
  timerEl.textContent = formatTime(timeLeft);
}

function setMode(newMode) {
  mode = newMode;
  timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
  isRunning = false;
  clearInterval(timerId);
  timerId = null;
  endTime = null;
  startPauseBtn.textContent = 'START';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
  modeEl.textContent = mode === 'work' ? 'WORK' : 'BREAK';
  workBtn.classList.toggle('active', mode === 'work');
  workBtn.setAttribute('aria-pressed', mode === 'work');
  breakBtn.classList.toggle('active', mode === 'break');
  breakBtn.setAttribute('aria-pressed', mode === 'break');
  updateDisplay();
}

function tick() {
  const now = Date.now();
  const remaining = Math.max(0, Math.round((endTime - now) / 1000));
  timeLeft = remaining;
  updateDisplay();
  if (remaining <= 0) {
    clearInterval(timerId);
    timerId = null;
    isRunning = false;
    startPauseBtn.textContent = 'START';
    startPauseBtn.setAttribute('aria-label', 'Start timer');
    if (mode === 'work') {
      setMode('break');
    } else {
      setMode('work');
    }
  }
}

function startTimer() {
  if (isRunning) return;
  isRunning = true;
  endTime = Date.now() + timeLeft * 1000;
  timerId = setInterval(tick, 200);
  startPauseBtn.textContent = 'PAUSE';
  startPauseBtn.setAttribute('aria-label', 'Pause timer');
}

function pauseTimer() {
  if (!isRunning) return;
  isRunning = false;
  clearInterval(timerId);
  timerId = null;
  timeLeft = Math.max(0, Math.round((endTime - Date.now()) / 1000));
  updateDisplay();
  startPauseBtn.textContent = 'START';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
}

function resetTimer() {
  isRunning = false;
  clearInterval(timerId);
  timerId = null;
  endTime = null;
  timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
  startPauseBtn.textContent = 'START';
  startPauseBtn.setAttribute('aria-label', 'Start timer');
  updateDisplay();
}

startPauseBtn.addEventListener('click', () => {
  if (isRunning) {
    pauseTimer();
  } else {
    startTimer();
  }
});

resetBtn.addEventListener('click', resetTimer);

workBtn.addEventListener('click', () => {
  if (mode !== 'work') setMode('work');
});

breakBtn.addEventListener('click', () => {
  if (mode !== 'break') setMode('break');
});

setMode('work');
